// Puts the mobile web app (one html file, see server/bundle.js) inside the phone app: src/bundle.js.
// Runs before every build (npm run bundle; the IPA workflow does it too).
const fs = require('fs');
const path = require('path');
const { build } = require('../../server/bundle');

const { version, html } = build();
const out = path.join(__dirname, '..', 'src', 'bundle.js');
fs.mkdirSync(path.dirname(out), { recursive: true });
fs.writeFileSync(out, `// generated by scripts/make-bundle.js — do not edit\nexport const VERSION = ${JSON.stringify(version)};\nexport default ${JSON.stringify(html)};\n`);
console.log(`bundle ${version}: ${(html.length / 1024).toFixed(0)} KB -> src/bundle.js`);
